insert into public.controle_patterns (id, nr, titel, uitleg, regel, controle, bron_case, aangemaakt, bijgewerkt, geverifieerd, door_user_id, door_naam, versie, rij_bijgewerkt) values
  ('addon-upsell-dubbel', 5, 'Add-on (Ponto, Peppol) meermaals aangemaakt of gecrediteerd zonder het contract aan te passen', 'Bij het activeren van Ponto of Peppol worden 3 tot 5 upsell-orders binnen enkele seconden aangemaakt. Daarna wordt er een gefactureerd, worden andere geannuleerd of gecrediteerd, en blijft het contract dubbele lijnen of een te hoog aantal houden. Bij de verlenging wordt dat aangerekend.', 'Eén upsell per add-on. Een dubbel annuleren vóór je bevestigt. Crediteer je een add-on, verlaag dan ook het aantal op het contract.', 'Aantal Ponto- en Peppol-eenheden op het contract = aantal rekeningen dat de klant echt koppelt = aantal dat dit jaar betaald is.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('correctie-op-de-factuur-niet-op-het-abonnement', 23, 'Correctie op de factuur, niet op het abonnement', 'Een factuur wordt gecrediteerd en vervangen door een nieuwe met andere facturatiegegevens (bijvoorbeeld op vraag van de klant), maar het abonnement en de order zelf blijven met de oude gegevens staan. Ook de volgende factuurdatum wordt niet teruggezet na de creditnota. Bij de volgende verlenging of factuur worden opnieuw de oude gegevens van het abonnement gebruikt en is de correctie verdwenen. De klant krijgt dan opnieuw een foute factuur, en de volgende factuurdatum staat verkeerd of ver in de toekomst.', 'Pas elke wijziging in facturatiegegevens of factuurdatum ook aan op het abonnement (en de order) zelf, niet enkel op de factuur. Controleer na een creditnota en vervangende factuur de volgende factuurdatum en zet ze juist. Noteer in de chatter van het abonnement wat er gewijzigd is en waarom.', 'Voor elk abonnement met een gecrediteerde en vervangen factuur: de facturatiegegevens van de laatste geldige factuur zijn gelijk aan die op het abonnement, en de volgende factuurdatum is gelijk aan de vorige factuurdatum + 1 periode (bij een jaarabonnement exact 1 jaar).', 'c004', '2026-10-13T12:00:15.180Z', '2026-10-13T12:00:15.180Z', NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('correctie-via-creditnota', 12, 'Correctie met creditnota en nieuwe factuur loopt mis', 'Om een factuur te corrigeren (datum, betaaltermijn, aantal) wordt ze gecrediteerd en opnieuw gemaakt, soms drie keer na elkaar. Daarbij ontstaan dubbele creditnota''s, blijven conceptfacturen hangen, en schuift de volgende factuurdatum mee. Netto per periode klopt het dan niet meer, of wel maar niemand kan het nog volgen.', 'Eén correctie = één creditnota met "Annuleren en nieuw concept", op de factuur zelf. Daarna nakijken: netto per periode = contractbedrag, en de volgende factuurdatum klopt.', 'Per abonnementsperiode: facturen min creditnota''s = contractbedrag.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('creditnota-zonder-vervolg', 2, 'Gecrediteerd, daarna niets', 'Een factuur van een lopend abonnement wordt volledig gecrediteerd en er volgt geen nieuwe factuur en geen stopzetting. Het abonnement blijft op lopend staan en telt mee in de cijfers, terwijl er niets meer gefactureerd wordt. De volgende factuurdatum blijft dan achter of staat fout, en de klant blijft op Active. Vaak is er geen reden of einddatum terug te vinden in Odoo.', '1. Vraag na wat de reden van de creditnota is (sales of klant) voor je beslist.
2. Kies op het lopende abonnement één van deze opties: opnieuw factureren, stopzetten of "Niet gefactureerde klant" aanvinken (intern of gratis gebruik). Gaat de klant over naar facturatie via een expert of naar beheer, controleer dan dat het nieuwe contract klopt.
3. Opnieuw factureren: factureer ook de achterstand en zet de volgende factuurdatum juist.
4. Stopzetten: geef de reden en de einddatum in en zet de klantstatus op Inactive met opzegreden. Sales geeft de stopzetting in.
5. Noteer de reden van de creditnota en de gekozen optie in de chatter.', 'Geen lopend abonnement waarvan de laatste factuur volledig gecrediteerd is, tenzij de chatter de reden en de gekozen optie vermeldt. Geen lopend abonnement dat niet gefactureerd wordt zonder het vinkje "Niet gefactureerde klant".', NULL, NULL, '2026-10-13T11:42:10.728Z', '2026-10-13T11:42:10.728Z', NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('dubbel-abonnement', 13, 'Abonnement twee keer aangemaakt', 'Voor een klant die al een abonnement heeft, wordt een tweede gemaakt in plaats van een upsell of verlenging. Het wordt daarna gecrediteerd met de reden "Duplicate Subscription Created". Netto klopt het meestal, maar de klant telt als gestopt en als nieuw.', 'Vóór je een abonnement aanmaakt: de klant opzoeken (ook zijn dubbels) en kijken of er een lopend abonnement is. Een wijziging is een upsell of een verlenging op het bestaande abonnement, nooit een nieuw abonnement.', 'Eén lopend abonnement per klant.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('dubbele-partner', 20, 'Bedrijf of VME twee keer in Odoo', 'Dezelfde VME of syndicus staat er meer dan één keer in. De lead, de status en het abonnement hangen dan aan verschillende exemplaren: een gewonnen verkoopkans op het ene, het abonnement op het andere.', 'Vóór je een bedrijf aanmaakt zoeken op naam, adres en ondernemingsnummer. Een dubbel samenvoegen (Actie, Samenvoegen), niet archiveren.', 'Geen twee actieve bedrijven met dezelfde naam en postcode.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('expert-zonder-abonnement', 15, 'Facturatie via expert zonder abonnement bij de expert', 'Een VME zet "facturatie via expert" aan en haar eigen abonnement wordt gecrediteerd of stopgezet, maar de expert heeft geen lopend abonnement waarin die kavels zitten. Dan betaalt niemand.', 'Het vinkje "facturatie via expert" pas aanzetten als de kavels van het gebouw in het abonnement van de expert zitten (upsell op zijn contract). Het eigen abonnement pas daarna crediteren.', 'Elke expert met gebouwen "via expert" heeft een lopend abonnement met minstens de kavels van die gebouwen.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('factuurperiode-loopt-voor-op-de-abonnementsperio', 24, 'Factuurperiode loopt voor op de abonnementsperiode', 'Een factuur die aan een abonnement hangt, heeft datums van een latere periode dan die waarin het abonnement zich bevindt (bijvoorbeeld een factuur voor jaar 2 terwijl het abonnement nog in jaar 1 zit). De volgende factuurdatum schuift dan een volledige periode te ver op, het abonnement lijkt al een periode verder te staan dan betaald of gefactureerd is, en een correctie of creditnota op die factuur laat het abonnement zonder geldige factuur voor de lopende periode. Daardoor wordt er niet meer gefactureerd, zonder dat iemand het ziet.', 'Controleer bij elke factuur op een abonnement dat de factuurperiode overeenkomt met de periode van het abonnement waarin ze valt. Corrigeer een factuur met de verkeerde periode eerst op de factuur zelf (datums), en zet daarna de volgende factuurdatum van het abonnement terug op de juiste datum (begin van de volgende periode). Laat een factuur van een latere periode nooit actief op het abonnement staan. Noteer de correctie in de chatter.', 'Lijst van abonnementen waarvan de volgende factuurdatum meer dan één periode na de startdatum of de laatste factuurperiode ligt, of waarvan een actieve factuur een periode dekt die na de huidige abonnementsperiode begint, moet leeg zijn. Voor elk lopend abonnement geldt: volgende factuurdatum = einde van de laatst gefactureerde periode + 1 dag.', 'c004', '2026-10-13T12:03:33.218Z', '2026-10-13T12:03:33.218Z', NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('gegevens', 11, 'Gegevens op klant of order', 'Order op een contactpersoon, ontbrekend aantal appartementen, datums die niet kloppen, een ongewoon lange eerste periode.', 'Een order staat op de VME of het bedrijf, nooit op een persoon. Het aantal appartementen is ingevuld voor je een licentie per kavel verkoopt.', 'Klant op de order is een bedrijf; aantal appartementen gekend.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('gratis-zonder-vinkje', 10, 'Gratis zonder "Niet gefactureerde klant"', 'Een licentie staat aan € 0 maar de klant is niet als gratis gemarkeerd. Hij telt dan als betalend abonnement zonder omzet.', 'Wie gratis gebruikt, krijgt het vinkje "Niet gefactureerde klant". Een licentie aan € 0 zonder dat vinkje bestaat niet.', 'Geen lopend abonnement aan € 0 zonder het vinkje.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('korting-btw', 7, 'Korting met de verkeerde btw', 'Het product "Discount" staat op btw "21%" (exclusief), de licenties op "21% (Incl.)". Een kortingsbedrag dat inclusief bedoeld is, wordt zo 21% groter.', 'Een kortingsbedrag altijd exclusief btw ingeven (inclusief bedrag ÷ 1,21), of het product "Discount" omzetten naar "21% (Incl.)".', 'Korting × 1,21 = het bedrag dat de klant als korting hoort te zien.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('lead-niet-afgesloten', 21, 'Verkoopkans niet correct afgesloten', 'Een kans staat op verloren terwijl de klant tekende, staat op gewonnen bij een ander bedrijf dan dat van de order, of is gesloten zonder reden. De conversie per kanaal en per verkoper klopt dan niet.', 'Een kans wordt gewonnen bij het bevestigen van de order, op het bedrijf van die order. Verloren enkel met een reden; een dubbel krijgt de reden "Dubbel".', 'Elke klant met een eerste abonnement heeft één gewonnen kans; geen verloren kans zonder reden.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('maandfacturatie-gestopt', 9, 'Maandvernieuwing niet aangemaakt', 'Een maandabonnement krijgt op de vervaldatum geen nieuwe periode en geen factuur.', 'De dag na de maandvernieuwing nakijken of elk maandabonnement een nieuwe factuur kreeg.', 'Geen maandabonnement met een volgende factuurdatum die voorbij is.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('offerte-open', 18, 'Offerte of upsell blijft openstaan', 'Een offerte of upsell wordt verzonden en niet meer opgevolgd. Ze kan maanden later nog bevestigd worden, ook als ze niet meer klopt. En gebruikt de klant de add-on al, dan betaalt hij er niet voor.', 'Een offerte die na 30 dagen niet bevestigd is, wordt opgevolgd en daarna bevestigd of geannuleerd.', 'Geen offerte ouder dan 30 dagen op "verzonden".', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('onbetaald', 8, 'Factuur niet betaald', 'Een factuur staat meer dan 30 dagen na de vervaldag open. Bij maandabonnementen stopt de vernieuwing dan soms.', 'Aanmanen na 15 en na 30 dagen. Na 60 dagen beslissen of het abonnement doorloopt.', 'Geen factuur van een lopend abonnement die meer dan 30 dagen vervallen is.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('opstarthulp-korting', 16, 'Opstarthulp gratis of met korting zonder reden', 'Opstarthulp (€ 250 incl.) wordt aan € 0, met 50% of 100% korting, of tegen een andere prijs verkocht, of achteraf gecrediteerd, zonder dat er staat waarom.', 'Korting op opstarthulp enkel met een reden in de chatter (welke actie of afspraak). Nooit achteraf crediteren zonder reden, nooit de lijn verwijderen nadat ze gefactureerd is.', 'Opstarthulp aan € 206,61 excl., of een reden in de chatter.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('oude-jaarlicentie', 14, 'Jaarlicentie van de oude facturatie zonder opvolging', 'In 2025 kochten professionele syndici een jaarlicentie "OpenVME Pro" als losse order, zonder abonnement. Bij de overstap naar de nieuwe facturatie (29/01/2026, reden "Migrating to the new client invoice logic") werden de lopende jaarabonnementen stopgezet. Wie geen Professional-abonnement in de plaats kreeg, wordt na het einde van het betaalde jaar niet meer gefactureerd, en telt tot dan niet mee in de ARR.', 'Elke klant die van de oude naar de nieuwe facturatie gaat, krijgt meteen een abonnement met als startdatum het einde van zijn betaalde periode.', 'Elke professionele syndicus op Active heeft een lopend abonnement, of al zijn gebouwen hebben er een.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('prijs-afwijkend', 17, 'Prijs wijkt af van de prijslijst', 'De eenheidsprijs van een licentie wordt in de orderlijn overschreven in plaats van via een prijslijst of een korting. Nieuwe klanten in dezelfde periode betalen dan verschillende prijzen voor hetzelfde product.', 'Een andere prijs gaat via een prijslijst (actie, partner) of via een korting met reden, nooit door de eenheidsprijs te overschrijven.', 'Eenheidsprijs = prijslijst; anders een korting met reden.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('startfactuur-dubbel', 1, 'Tweede factuur bij de start, daarna gecrediteerd', 'Bij de start van een abonnement wordt soms een tweede factuur gemaakt (dezelfde dag of kort erna, meestal door sales), die later wordt gecrediteerd of geannuleerd. Odoo zet de volgende factuurdatum bij elke factuur een periode verder en zet ze bij een creditnota of annulatie niet terug. Gevolg: de klant wordt een jaar of meer (bij een maandabonnement een maand of meer) niet gefactureerd, en dat valt vaak pas maanden later op. Het eigenlijke probleem is dat die tweede factuur niet gemaakt had mogen worden.', '1. Maak nooit een tweede factuur voor dezelfde periode op hetzelfde abonnement. Staat er al een factuur voor die periode, meld dan duidelijk dat een tweede factuur niet de bedoeling is.
2. Crediteer of annuleer je toch een factuur van een abonnement: kijk meteen de volgende factuurdatum na en zet ze terug op het einde van de betaalde periode. Elke factuur verschuift de datum een periode, tel dat dus niet onnodig op.
3. Ga na of de gecrediteerde factuur eigenlijk de volgende periode was. Zo ja: factureer die periode alsnog.
4. Staan er twee betaalde facturen voor dezelfde periode: crediteer er één en betaal terug of verreken.
5. Pas je de volgende factuurdatum aan: kijk na of er een nieuwe factuur klaarstaat als de datum al voorbij is of een periode niet gefactureerd werd, en maak die aan.', 'Per abonnementsperiode is er maximaal één lopende factuur en geldt: facturen min creditnota''s = contractbedrag. De volgende factuurdatum = einde van de laatste betaalde periode (startdatum + 12 maanden bij een jaarplan, + 1 maand bij een maandplan, gerekend vanaf die periode). Geen lopend abonnement waarvan de volgende factuurdatum later ligt dan het einde van de betaalde periode.', NULL, NULL, '2026-10-13T11:17:00.689Z', '2026-10-13T11:17:00.689Z', NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('status-klopt-niet', 19, 'Klantstatus klopt niet met het abonnement', 'Active of Pending Payment zonder abonnement of zonder openstaande factuur, Free Trial na een stopzetting, of helemaal geen status. Lijsten, rapporten en de toegang tot het platform steunen op die status.', 'De status volgt het abonnement: lopend en betaald = Active; factuur meer dan 30 dagen vervallen = Pending Payment; gestopt = Inactive, met een opzegreden. Nooit terug naar Free Trial.', 'Geen Active of Pending Payment zonder lopend abonnement (bij een professionele syndicus: zonder betalende gebouwen).', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('testdata', 22, 'Testgegevens tussen echte klanten', 'Testbedrijven, testoffertes en testleads staan tussen de echte gegevens, met een status alsof het klanten of prospecten zijn.', 'Testen in een aparte database, of met één vaste testklant op status Internal met "Niet gefactureerde klant". Na een test de offertes annuleren en het bedrijf archiveren.', 'Geen bedrijf met test of demo in de naam buiten status Internal.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('upsell-volledige-samenstelling', 6, 'Upsell met de volledige samenstelling in plaats van het verschil', 'Een upsell bevat alle producten van het nieuwe contract in plaats van enkel wat bijkomt of wijzigt, en lijnen van het lopende contract worden met de hand verwijderd. De upsell staat dan op "te factureren" voor een bedrag dat al betaald is, en factuurlijnen hangen aan geen orderlijn meer.', 'Een upsell bevat enkel wat bijkomt of wijzigt. Een productwissel = een negatieve lijn voor het oude product en een positieve voor het nieuwe. Verwijder nooit lijnen van een contract dat al gefactureerd is.', 'Geen upsell op "te factureren" waarvan het bedrag de volledige jaarprijs is.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('verlenging-niet-opgevolgd', 3, 'Verlengingsofferte blijft op "verzonden"', 'De verlengingsofferte wordt verstuurd maar niet bevestigd. Het abonnement loopt door aan de oude prijs, het nieuwe jaar wordt niet gefactureerd, en de klant staat op "Pending Payment".', 'Een verlengingsofferte die op de vervaldag niet bevestigd is, wordt binnen een week opgevolgd. Na 30 dagen: bevestigen of stopzetten.', 'Geen verlengingsofferte die meer dan 30 dagen na de vervaldag nog op "verzonden" staat.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z'),
  ('verlenging-ontbreekt', 4, 'Geen verlenging aangemaakt', 'Aan het einde van de periode is er geen verlengingsofferte en geen factuur gemaakt; het abonnement blijft op lopend staan.', 'Elk jaarabonnement krijgt vóór de vervaldag een verlengingsofferte of een stopzetting.', 'Geen lopend abonnement waarvan de volgende factuurdatum meer dan 14 dagen voorbij is.', NULL, NULL, NULL, NULL, NULL, NULL, 0, '2026-10-16T07:28:44.783Z')
on conflict (id) do update set nr = excluded.nr, titel = excluded.titel, uitleg = excluded.uitleg, regel = excluded.regel, controle = excluded.controle, bron_case = excluded.bron_case, aangemaakt = excluded.aangemaakt, bijgewerkt = excluded.bijgewerkt, geverifieerd = excluded.geverifieerd, door_user_id = excluded.door_user_id, door_naam = excluded.door_naam, versie = excluded.versie, rij_bijgewerkt = excluded.rij_bijgewerkt;

insert into public.controle_cases (id, nr, klant, klanttype, titel, bedrag, categorie, domein, prio, prio_rang, zekerheid, soort, deadline, vervaldag, bevinding, voorstel, refs, onderzocht, rechtgezet, geen_fout, in_openvme, vasthouden, wat_gebeurde, actie, complicaties, les, bijgewerkt, tekst_bijgewerkt, geverifieerd, door_user_id, door_naam, aangemaakt, versie, rij_bijgewerkt) values
  ('c001', 1, 'SBS 745', 'VME in beheer', 'Volgende factuur staat een jaar te ver, vervaldag 21/10/2026', '€ 981,84 ARR', 'Volgende factuurdatum te ver', 'abonnement', 'dringend', 1, 'zeker', 'dubbel', '2026-10-21', NULL, 'Start 21/10/2025. CFVK/2025/00197 (21/10/2025) is betaald. Op 24/10/2025 is een tweede factuur gemaakt (CFVK/2025/00201) en die is op 22/01/2026 gecrediteerd (CFVK/2026/00047). Odoo zette de volgende factuurdatum daarbij een jaar verder: 21/10/2027 in plaats van 21/10/2026.', 'Volgende factuurdatum op S00514 terugzetten naar 21/10/2026, vóór die datum.', '[{"id":906860,"label":"SBS 745","model":"res.partner"},{"id":514,"label":"S00514","model":"sale.order"},{"id":17212,"label":"CFVK/2025/00197","model":"account.move"},{"id":17311,"label":"CFVK/2025/00201","model":"account.move"},{"id":20475,"label":"CFVK/2026/00047","model":"account.move"}]'::jsonb, true, true, false, false, false, 'Er werd twee keer op hetzelfde moment een factuur gemaakt, wss door sales. Elk van die facturen verzette de volgende factuurdatum een jaar verer. Het crediteren verzette die datum niet terug. Aand de bron zit het probleem dat die tweede fac tuur niet gemaakt had mogen worden, want het heeft ook maanden geduurd voor het opgevallen is, en dat is rommel.', 'We zouden de datum terug kunnen zetten, maar de skill moet eigenlijk al vroeger in gang schieten en verhindern dat er twee abonnementsfacturen voor dezelfde periode aan hetzelfde abonnement hangen. ', '', '', '2026-10-13T11:22:04.670Z', NULL, NULL, NULL, NULL, '2026-10-13T11:22:04.670Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c002', 2, 'Residentie Da Vinci', 'VME in advies', 'Jaar liep af op 06/11/2025: geen verlenging en geen factuur', '€ 287,64 ARR, ± 11 maanden', 'Facturatie ligt stil', 'abonnement', 'dringend', 1, 'zeker', 'opvolging', NULL, NULL, 'Jaarabonnement (early adopter, € 287,60 excl.). De laatste factuur, CFVK/2025/00064 (18/04/2025), dekte 07/11/2024 tot 06/11/2025. Daarna is er geen verlengingsofferte en geen factuur gemaakt; het abonnement staat nog op lopend.', 'Navragen of de VME het platform nog gebruikt. Zo ja: verlengen en factureren vanaf 07/11/2025. Zo nee: stopzetten.', '[{"id":472,"label":"Residentie Da Vinci","model":"res.partner"},{"id":46,"label":"S00046","model":"sale.order"},{"id":11569,"label":"CFVK/2025/00064","model":"account.move"}]'::jsonb, true, false, false, true, true, 'Het jaarabonnement (S00046) liep af op 06/11/2025. De laatste factuur, CFVK/2025/00064 (18/04/2025), dekte 07/11/2024 tot 06/11/2025. Daarna werd er geen verlengingsofferte en geen factuur aangemaakt en het abonnement staat nog op lopend. Waarschijnlijk toonde OpenVME een vervaldatum die te ver in de toekomst lag, terwijl de vervaldatum in Odoo wel juist was. Daardoor is de afloop niet opgemerkt.', '', 'Als we dit nu rechtzetten gaat die een factuur krijgen voor vorig jaar en op 6 november de factuur voor volgend jaar.', 'Vergelijk de vervaldatum in OpenVME met die in Odoo en zorg dat ze correct gesynchroniseerd worden.', '2026-10-13T11:36:05.740Z', '2026-10-13T11:36:05.740Z', '2026-10-13T11:32:36.351Z', NULL, NULL, '2026-10-13T11:36:05.740Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c003', 3, 'Bebrimmo', 'Professionele syndicus', 'Februari gecrediteerd, sinds maart niets meer gefactureerd', '8 × € 85,50 = € 684 excl.', 'Facturatie ligt stil', 'facturatie', 'dringend', 1, 'waarschijnlijk', 'creditnota', NULL, NULL, 'Maandabonnement (Professional, 342 eenheden, € 85,50 excl. per maand). De factuur van februari (CFVK/2026/00058) is op 30/04 volledig gecrediteerd (CFVK/2026/00255). Sindsdien is er geen maandfactuur meer gemaakt; de volgende factuurdatum staat nog op 01/03/2026.', 'Navragen waarom gecrediteerd. Dan facturatie hervatten (en de achterstand factureren) of het abonnement stopzetten.', '[{"id":362,"label":"Bebrimmo","model":"res.partner"},{"id":729,"label":"S00729","model":"sale.order"},{"id":20828,"label":"CFVK/2026/00058","model":"account.move"},{"id":39156,"label":"CFVK/2026/00255","model":"account.move"}]'::jsonb, true, true, false, false, false, 'De factuur van februari (CFVK/2026/00058) werd op 30/04 volledig gecrediteerd (CFVK/2026/00255). Sindsdien werd er geen maandfactuur meer gemaakt; de volgende factuurdatum bleef op 01/03/2026 staan. Waarschijnlijk is de klant gestopt, maar het abonnement S00729 bleef lopen en de klant bleef actief staan, omdat het een professionele klant is. In Odoo was geen informatie over een stopzetting terug te vinden.', 'We zetten het abonnement S00729 manueel stop.', 'Het abonnement stond nog op volgende factuurdatum 01/03/2026, waardoor een achterstand van 8 × € 85,50 = € 684 excl. ongefactureerd bleef. Het is nog niet duidelijk of die achterstand nog gefactureerd moet worden; dat hangt af van de reden van de creditnota en de effectieve einddatum van de klant. Die reden is nog na te vragen bij sales of de klant.', 'Volg stopzettingen op: geef de reden en de einddatum in en pas alles correct aan in Odoo. Sales geeft de stopzetting in; de sync van OpenVME naar Odoo moet ze doorgeven. Beslis na elke creditnota op een lopend abonnement (opnieuw factureren, stopzetten of ''Niet gefactureerde klant'' aanvinken) en noteer de reden in de chatter.', '2026-10-13T11:40:38.960Z', '2026-10-13T11:38:58.400Z', '2026-10-13T11:40:38.959Z', NULL, NULL, '2026-10-13T11:40:38.960Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c004', 4, 'VME Res. Acacia', 'VME in advies', 'Enige factuur van dit jaar volledig gecrediteerd', '€ 981,84 ARR', 'Facturatie ligt stil', 'facturatie', 'dringend', 1, 'waarschijnlijk', 'creditnota', NULL, NULL, 'Unlimited, € 981,82 excl. per jaar. CFVK/2026/00211 (08/04, € 1.188 incl.) is op 20/04 volledig gecrediteerd (CFVK/2026/00230). Er volgde geen nieuwe factuur. De volgende factuurdatum staat bovendien op 08/04/2028.', 'Navragen waarom gecrediteerd. Opnieuw factureren, of als gratis markeren. Volgende factuurdatum op 08/04/2027 zetten.', '[{"id":913349,"label":"VME Res. Acacia","model":"res.partner"},{"id":914,"label":"S00914","model":"sale.order"},{"id":38024,"label":"CFVK/2026/00211","model":"account.move"},{"id":38611,"label":"CFVK/2026/00230","model":"account.move"}]'::jsonb, true, false, false, false, true, 'Het abonnement (order S00914, Unlimited) factureerde automatisch op basis van de gegevens van het gebouw. Factuur CFVK/2026/00211 van 08/04 (€ 1.188 incl.) werd op 20/04 volledig gecrediteerd met CFVK/2026/00230. Waarschijnlijk had de klant andere facturatiegegevens gevraagd, maar dat is niet bevestigd. Er volgde geen nieuwe factuur. De volgende factuurdatum van het abonnement staat op 08/04/2028 in plaats van 08/04/2027.', '', 'Er staat dit jaar geen geldige factuur meer open voor deze klant; de reden van de creditnota is nog niet nagevraagd. Het rechtzetten (nieuwe factuur of als gratis markeren, en de volgende factuurdatum terugzetten op 08/04/2027) moet met de administratie bekeken worden. Het factuuradres of de facturatiegegevens moeten op het abonnement zelf gewijzigd worden, niet op de factuur. De case wacht op goedkeuring; vermeld nog van wie.', 'Pas gewijzigde facturatiegegevens aan op het abonnement zelf, niet enkel op de factuur. Controleer na een creditnota de volgende factuurdatum en noteer de wijziging in de chatter.', '2026-10-13T12:08:03.133Z', '2026-10-13T12:06:57.609Z', '2026-10-13T12:08:03.132Z', NULL, NULL, '2026-10-13T12:08:03.133Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c005', 5, 'VME Da Vinci 2', 'VME in advies', 'Tweede jaar (22/05/2026–2027) niet gefactureerd', '€ 309,36 ARR', 'Facturatie ligt stil', 'facturatie', 'dringend', 1, 'waarschijnlijk', 'dubbel', NULL, NULL, 'Boekhouding Solo min korting, € 309,42 excl. per jaar. Jaar 1 is betaald (CFVK/2025/00082, 22/05/2025). Een tweede factuur (CFVK/2025/00115, 17/07/2025) is pas op 04/06/2026 gecrediteerd (CFVK/2026/00331). Daardoor staat jaar 2 niet gefactureerd en de volgende factuurdatum op 22/05/2027.', 'Nagaan of CFVK/2025/00115 eigenlijk jaar 2 was en waarom ze gecrediteerd werd. Zo niet: jaar 2 factureren.', '[{"id":75963,"label":"VME Da Vinci 2","model":"res.partner"},{"id":267,"label":"S00267","model":"sale.order"},{"id":13859,"label":"CFVK/2025/00082","model":"account.move"},{"id":15011,"label":"CFVK/2025/00115","model":"account.move"},{"id":40698,"label":"CFVK/2026/00331","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c006', 6, 'Vastgoed Janssens', 'Professionele syndicus', '8 maandfacturen open, oudste sinds februari; oktober niet meer gefactureerd', '€ 264,99 incl. open', 'Onbetaald', 'facturatie', 'dringend', 1, 'zeker', 'opvolging', NULL, '2026-03-03', 'Maandabonnement (€ 22 excl. per maand). Open: 8 facturen, samen € 264,99 incl.; de oudste is CFVK/2026/00062 (01/02). De maandfactuur van oktober is niet aangemaakt (volgende factuurdatum 01/10).', 'Contact opnemen over de achterstand. Beslissen of het abonnement doorloopt.', '[{"id":59326,"label":"Vastgoed Janssens","model":"res.partner"},{"id":1295,"label":"S01300","model":"sale.order"},{"id":20832,"label":"CFVK/2026/00062","model":"account.move"},{"id":44197,"label":"CFVK/2026/00505","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c007', 7, 'AGERIS BY SYNDIA', 'Professionele syndicus', '6 maandfacturen open, oudste sinds april; oktober niet meer gefactureerd', '€ 948,20 incl. open', 'Onbetaald', 'facturatie', 'dringend', 1, 'zeker', 'opvolging', NULL, '2026-05-01', 'Maandabonnement (€ 129,91 excl. per maand). Open: 6 facturen, samen € 948,20 incl.; de oudste is CFVK/2026/00190 (01/04). De maandfactuur van oktober is niet aangemaakt (volgende factuurdatum 01/10).', 'Contact opnemen over de achterstand. Beslissen of het abonnement doorloopt.', '[{"id":910106,"label":"AGERIS BY SYNDIA","model":"res.partner"},{"id":1302,"label":"S01307","model":"sale.order"},{"id":37599,"label":"CFVK/2026/00190","model":"account.move"},{"id":44208,"label":"CFVK/2026/00512","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c008', 8, 'SOBEVA BV', 'Professionele syndicus', 'Maandfactuur oktober niet aangemaakt', '€ 141,36 ARR', 'Maandfacturatie gestopt', 'abonnement', 'dringend', 1, 'waarschijnlijk', 'onbekend', NULL, NULL, 'Maandabonnement (€ 11,78 excl. per maand). De volgende factuurdatum staat op 01/10 en er is geen factuur voor oktober. De factuur van september (€ 14,26) staat 1 week open. Andere maandabonnementen werden op 01/10 wel vernieuwd; een reden is niet zichtbaar.', 'Nagaan waarom de vernieuwing niet liep (betaalmethode? handmatig gestopt?) en oktober factureren.', '[{"id":905907,"label":"SOBEVA BV","model":"res.partner"},{"id":1300,"label":"S01305","model":"sale.order"},{"id":44202,"label":"CFVK/2026/00510","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c009', 9, 'Res. Vremde 7', 'VME in beheer', 'Verlengingsofferte S01199 staat open; vervaldag 16/07/2026', '€ 942,12 ARR (was € 803,28)', 'Verlenging niet bevestigd', 'abonnement', 'dringend', 1, 'zeker', 'opvolging', NULL, '2026-07-16', 'De lopende periode van S00334 liep af op 16/07/2026. Verlengingsofferte S01199 staat op "verzonden" en is niet bevestigd, dus het nieuwe jaar is niet gefactureerd. In Odoo staat de klant op "Pending Payment". De offerte is duurder dan het lopende contract (€ 78,51 tegenover € 66,94 per maand); mogelijk wacht de klant daarom.', 'Klant opvolgen: offerte laten bevestigen en factureren, of het abonnement stopzetten.', '[{"id":131220,"label":"Res. Vremde 7","model":"res.partner"},{"id":334,"label":"S00334","model":"sale.order"},{"id":1194,"label":"S01199","model":"sale.order"}]'::jsonb, false, false, false, false, false, 'Kobe heeft de vraag aan Rob gesteld.
Alvast een vermoede: het gebouw is van eigenaar beheer naar PS beheer gegaan, maar het bijhorende abonnement is niet over gezet. Waarschijnlijk moet dus het huidige abonnement afgesloten worden en moet een nieuwe (met correcte data) opgestart worden. ', '', '', '', '2026-10-13T12:37:16.886Z', '2026-10-13T12:37:16.886Z', NULL, NULL, NULL, '2026-10-13T12:37:16.886Z', 0, '2026-10-16T07:28:44.783Z'),
