  ('c044', 44, 'Guyot Immo', 'Professionele syndicus', 'Order van 01/10 met startdatum 01/06 en volgende factuur 01/07', '€ 145,56 ARR', 'Datums kloppen niet', 'abonnement', 'gemiddeld', 3, 'zeker', 'ingave', NULL, NULL, 'De maandvernieuwing van oktober (S01379, aangemaakt 01/10) heeft startdatum 01/06/2026 en volgende factuurdatum 01/07/2026. De factuur van oktober (CFVK/2026/00564) is wel gemaakt. De prijs ging in september van € 4 naar € 12,13 per maand.', 'Datums op S01379 rechtzetten (start 01/10, volgende factuur 01/11) voor de facturatie een gemiste maand probeert in te halen.', '[{"id":906637,"label":"Guyot Immo","model":"res.partner"},{"id":1373,"label":"S01379","model":"sale.order"},{"id":45402,"label":"CFVK/2026/00564","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c045', 45, 'VME Gebouw Beerse Kerkplein 8', 'VME in advies', '3 kavels gefactureerd, 6 appartementen volgens Odoo', '3 × € 108 incl./jaar', 'Kavels', 'abonnement', 'gemiddeld', 3, 'waarschijnlijk', 'ingave', NULL, NULL, 'Smart wordt aangerekend voor 3 kavels; partner en actieblad zeggen 6 appartementen. Bij de andere gebouwen waar het aantal appartementen gekend is, wordt per appartement gefactureerd.', 'Aantal appartementen nakijken en de licentie bij de verlenging (30/07/2027) daarop zetten.', '[{"id":929693,"label":"VME Gebouw Beerse Kerkplein 8","model":"res.partner"},{"id":1223,"label":"S01228","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c046', 46, 'Résidence Juno', 'VME in advies', 'Unlimited aan € 0, zonder "Niet gefactureerde klant"', '€ 0', 'Gratis zonder vinkje', 'abonnement', 'gemiddeld', 3, 'zeker', 'afspraak', NULL, NULL, 'Unlimited aan € 0. Er zijn al twee facturen van € 0 gemaakt (CFVK/2026/00011 en 00012), de tweede voor 07/01/2027–06/01/2028; daarom staat de volgende factuurdatum op 07/01/2028. Het vinkje "Niet gefactureerde klant" staat niet aan.', 'Als gratis zo bedoeld is: vinkje aanzetten. Anders factureren.', '[{"id":906199,"label":"Résidence Juno","model":"res.partner"},{"id":667,"label":"S00667","model":"sale.order"},{"id":19328,"label":"CFVK/2026/00011","model":"account.move"},{"id":19343,"label":"CFVK/2026/00012","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
