  ('c053', 53, '21 klanten', 'VME in advies', '21 contracten hebben een eerste periode van 13 tot 16 maanden', 'administratief', 'Gegevens', 'abonnement', 'laag', 5, 'na te kijken', 'afspraak', NULL, NULL, 'De volgende factuurdatum ligt 13 tot 16 maanden na de start. Dat lijkt een bewuste gratis startmaand; als dat niet de afspraak is, wordt telkens een maand niet gefactureerd.', 'Bevestigen dat dit de afspraak is, en ze dan als bewust markeren.', '[{"id":542,"label":"S00542","model":"sale.order"},{"id":551,"label":"S00551","model":"sale.order"},{"id":588,"label":"S00588","model":"sale.order"},{"id":613,"label":"S00613","model":"sale.order"},{"id":748,"label":"S00748","model":"sale.order"},{"id":796,"label":"S00796","model":"sale.order"},{"id":855,"label":"S00855","model":"sale.order"},{"id":884,"label":"S00884","model":"sale.order"},{"id":894,"label":"S00894","model":"sale.order"},{"id":915,"label":"S00915","model":"sale.order"},{"id":978,"label":"S00978","model":"sale.order"},{"id":997,"label":"S00997","model":"sale.order"},{"id":1045,"label":"S01046","model":"sale.order"},{"id":1050,"label":"S01051","model":"sale.order"},{"id":1097,"label":"S01102","model":"sale.order"},{"id":1114,"label":"S01119","model":"sale.order"},{"id":1271,"label":"S01276","model":"sale.order"},{"id":1279,"label":"S01284","model":"sale.order"},{"id":1307,"label":"S01312","model":"sale.order"},{"id":1344,"label":"S01350","model":"sale.order"},{"id":1350,"label":"S01356","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c054', 54, '53 gebouwen', 'VME in advies', '53 gebouwen zonder aantal appartementen', 'administratief', 'Gegevens', 'partners', 'laag', 5, 'zeker', 'gegevens', NULL, NULL, 'Facturatie gebeurt per appartement; het veld "kavels" telt ook garages en bergingen. Waar het aantal appartementen ingevuld is, klopt de facturatie in 17 van de 20 gevallen. Bij 53 gebouwen met een lopend abonnement ontbreekt het, dus daar is het niet na te gaan.', 'Aantal appartementen invullen op het actieblad of de partner.', '[]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c055', 55, 'Immo Pauly', 'Professionele syndicus', 'Drie VME''s staan op "facturatie via expert", maar Immo Pauly heeft geen lopend abonnement', '€ 1.150 per jaar gecrediteerd, € 319,06 open', 'Via expert zonder abonnement', 'abonnement', 'hoog', 2, 'waarschijnlijk', 'upsell', NULL, NULL, 'VME Beterveld, VME Zavelpand II en VME Mheerstraat staan op "facturatie via expert" met Immo Pauly als expert. Hun eigen jaarabonnementen zijn stopgezet. Die van Zavelpand II en Mheerstraat werden op 01/10 volledig gecrediteerd: CFVK/2026/00574 (€ 991,74) en CFVK/2026/00571 (€ 158,68), allebei jaarfacturen van 07/05. Immo Pauly zelf heeft sinds mei geen lopend abonnement meer: S00972 is op 07/05 stopgezet en de upsell S00987 bracht het bedrag op € 0. Op 01/10 is wel een losse order S01385 "SyndicusOnline Registratie" (192 × € 1) gefactureerd en betaald. Daarnaast staat CFVK/2026/00271 van Beterveld (€ 319,06) open sinds 06/06.', 'Nagaan hoe Immo Pauly voortaan betaalt. Is "SyndicusOnline Registratie" de nieuwe manier, dan klopt het geld maar ziet het dashboard het niet, want het is geen abonnement. Zo niet: een Professional-abonnement voor Immo Pauly met de kavels van de drie gebouwen, vanaf de datum van de creditnota''s. Beterveld: de openstaande factuur opvolgen, of crediteren als ze in de periode via de expert valt.', '[{"id":906236,"label":"Immo Pauly","model":"res.partner"},{"id":906999,"label":"VME BETERVELD","model":"res.partner"},{"id":910281,"label":"VME ZAVELPAND II","model":"res.partner"},{"id":914490,"label":"VME MHEERSTRAAT","model":"res.partner"},{"id":972,"label":"S00972","model":"sale.order"},{"id":987,"label":"S00987","model":"sale.order"},{"id":1379,"label":"S01385","model":"sale.order"},{"id":984,"label":"S00984","model":"sale.order"},{"id":986,"label":"S00986","model":"sale.order"},{"id":45468,"label":"CFVK/2026/00574","model":"account.move"},{"id":45420,"label":"CFVK/2026/00571","model":"account.move"},{"id":39328,"label":"CFVK/2026/00271","model":"account.move"},{"id":45467,"label":"CFVK/2026/00573","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c056', 56, 'MCA Vlaanderen', 'Professionele syndicus', 'Jaarlicentie van 24/10/2025 loopt af; geen abonnement, en twee gebouwen factureren via MCA', '€ 287,60 per jaar (oude licentie)', 'Oude jaarlicentie', 'abonnement', 'hoog', 2, 'waarschijnlijk', 'opvolging', '2026-10-24', NULL, 'MCA Vlaanderen kocht op 24/10/2025 een jaarlicentie "OpenVME Pro" als losse order (S00482, CFVK/2025/00199, € 287,60), dus zonder abonnement. Medisch Centrum Assenede en Medisch Centrum Assenede New staan op "facturatie via expert" met MCA als expert, en hebben zelf geen abonnement. Na 24/10/2026 wordt voor die gebouwen niets meer gefactureerd.', 'Vóór 24/10 een abonnement voor MCA Vlaanderen maken (Professional per kavel, maandelijks) met start 24/10/2026.', '[{"id":373,"label":"MCA Vlaanderen","model":"res.partner"},{"id":907392,"label":"Medisch Centrum Assenede","model":"res.partner"},{"id":907393,"label":"Medisch Centrum Assenede New","model":"res.partner"},{"id":482,"label":"S00482","model":"sale.order"},{"id":17304,"label":"CFVK/2025/00199","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c057', 57, 'Flash Invest bv', 'Professionele syndicus', 'Professional-licentie "tot oktober"; nu loopt er enkel Ponto', '± € 109 per maand', 'Oude jaarlicentie', 'abonnement', 'hoog', 2, 'waarschijnlijk', 'opvolging', NULL, NULL, 'Het maandabonnement S00734 (Professional, 109 eenheden, € 109 per maand) werd in februari meteen gecrediteerd (CFVK/2026/00063, creditnota CFVK/2026/00076) en stopgezet met als reden "jaarlijkse licentie tot oktober". Die jaarlicentie is order S00561 (OpenVME Pro, 69 × € 9,92 = € 684,48, gefactureerd op 18/12/2025). Er loopt nu enkel een maandabonnement voor Ponto (S01376, 26 koppelingen). Voor de licentie zelf bestaat geen abonnement meer.', 'Nagaan tot welke datum de jaarlicentie liep. Vanaf die datum het Professional-abonnement (per kavel, maandelijks) opnieuw starten, en wat al verstreken is factureren.', '[{"id":59210,"label":"Flash Invest bv","model":"res.partner"},{"id":561,"label":"S00561","model":"sale.order"},{"id":734,"label":"S00734","model":"sale.order"},{"id":1370,"label":"S01376","model":"sale.order"},{"id":18849,"label":"CFVK/2025/00264","model":"account.move"},{"id":20833,"label":"CFVK/2026/00063","model":"account.move"},{"id":21030,"label":"CFVK/2026/00076","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c058', 58, 'Chris D''haese Comm. V', 'Professionele syndicus', 'Jaar betaald tot 14/01/2027, daarna is niets ingepland', '€ 1.421,93 per jaar', 'Oude jaarlicentie', 'abonnement', 'gemiddeld', 3, 'waarschijnlijk', 'opvolging', '2027-01-14', NULL, 'Op 14/01/2026 is een jaarabonnement "OpenVME PRO" van € 1.421,93 gefactureerd en betaald (S00683, CFVK/2026/00020). Twee weken later is het stopgezet met reden "Migrating to the new client invoice logic", zonder dat er een Professional-abonnement in de plaats kwam. Het Peppol-maandabonnement S00731 is in februari gecrediteerd (reden "Subscription is too expensive"). Nu loopt enkel Ponto per maand (S01368). Het betaalde jaar loopt tot 14/01/2027. Daarna wordt niets gefactureerd, en tot dan telt de klant niet mee in de ARR.', 'Een Professional-abonnement aanmaken met start 14/01/2027, of nu al met de eerste factuur op 14/01/2027.', '[{"id":394,"label":"Chris D''haese Comm. V","model":"res.partner"},{"id":683,"label":"S00683","model":"sale.order"},{"id":19776,"label":"CFVK/2026/00020","model":"account.move"},{"id":731,"label":"S00731","model":"sale.order"},{"id":1362,"label":"S01368","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c059', 59, 'Clabots', 'Professionele syndicus', 'Jaarlicentie van 25/11/2025 als losse order, geen abonnement erna', '€ 396,80 per jaar', 'Oude jaarlicentie', 'abonnement', 'gemiddeld', 3, 'waarschijnlijk', 'opvolging', '2026-11-25', NULL, 'Clabots kocht op 25/11/2025 een jaarlicentie "OpenVME Pro" als losse order (S00564, 40 × € 9,92 = € 396,80, CFVK/2025/00229) en heeft geen abonnement. De status staat op Active. Na 25/11/2026 wordt niets meer gefactureerd.', 'Vóór 25/11 een abonnement aanmaken (Professional per kavel) met start 25/11/2026.', '[{"id":58809,"label":"Clabots","model":"res.partner"},{"id":564,"label":"S00564","model":"sale.order"},{"id":18073,"label":"CFVK/2025/00229","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c060', 60, 'GEOVDP VOF', 'Professionele syndicus', 'Van jaarlicentie naar maandabonnement: juli en augustus 2026 mogelijk niet gefactureerd', '± € 347 per maand', 'Oude jaarlicentie', 'abonnement', 'gemiddeld', 3, 'na te kijken', 'opvolging', NULL, NULL, 'De jaarlicentie "OpenVME Pro" (S00305, 309 × € 9,92 = € 3.065,28) werd gefactureerd op 29/07/2025. Het Professional-maandabonnement begint pas op 01/09/2026 (S01296, 333 + 13 + 1 eenheden). Liep de jaarlicentie tot eind juli, dan is augustus 2026 niet gefactureerd. De jaarabonnementen voor Ponto (S00485, 17 koppelingen, € 843,03 betaald tot 13/10/2026, en S00513) zijn op 29/01 stopgezet voor de migratie, en sinds juli loopt Ponto ook per maand: van juli tot oktober is Ponto dus twee keer betaald (klein bedrag). Van CFVK/2026/00501 staat nog € 419,87 open. Er staat ook nog een offerte S00470 open (17 × Ponto, € 843,03) van oktober 2025.', 'Nagaan tot wanneer de jaarlicentie liep en de ontbrekende maand factureren. S00470 annuleren.', '[{"id":686,"label":"GEOVDP VOF","model":"res.partner"},{"id":305,"label":"S00305","model":"sale.order"},{"id":1291,"label":"S01296","model":"sale.order"},{"id":485,"label":"S00485","model":"sale.order"},{"id":513,"label":"S00513","model":"sale.order"},{"id":470,"label":"S00470","model":"sale.order"},{"id":15242,"label":"CFVK/2025/00129","model":"account.move"},{"id":44193,"label":"CFVK/2026/00501","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c061', 61, 'Provinciestraat 187-193', 'VME in advies', 'Jaarfactuur twee keer gecrediteerd: het jaar 2025-2026 staat netto op € 0', '€ 785,45 excl. (€ 950,40 incl.)', 'Correctie loopt mis', 'facturatie', 'hoog', 2, 'waarschijnlijk', 'dubbel', NULL, NULL, 'S00416 (Unlimited met 20% korting, € 785,45 excl.). De jaarfactuur CFVK/2025/00165 (25/09/2025) werd op 02/04/2026 gecrediteerd met twee creditnota''s van elk € 785,45 (CFVK/2026/00199 en CFVK/2026/00200), en dezelfde dag opnieuw gefactureerd (CFVK/2026/00204, betaald). Netto voor dat jaar: € 785,45 − 785,45 − 785,45 + 785,45 = € 0. Er hangen ook nog twee geannuleerde conceptfacturen aan.', 'In de boekhouding nakijken waartegen CFVK/2026/00200 afgeletterd is. Hoort ze er niet, dan annuleren of het bedrag opnieuw factureren. Was er een terugbetaling aan de klant, die rechtzetten.', '[{"id":747899,"label":"Provinciestraat 187-193","model":"res.partner"},{"id":416,"label":"S00416","model":"sale.order"},{"id":16487,"label":"CFVK/2025/00165","model":"account.move"},{"id":37821,"label":"CFVK/2026/00199","model":"account.move"},{"id":37836,"label":"CFVK/2026/00200","model":"account.move"},{"id":37889,"label":"CFVK/2026/00204","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c062', 62, 'Vossenhof', 'VME in advies', 'Contract voor 3 kavels, 1 kavel gefactureerd', '€ 119,01 per jaar', 'Te weinig gefactureerd', 'facturatie', 'gemiddeld', 3, 'waarschijnlijk', 'ingave', NULL, NULL, 'S01119: Basic, 3 kavels × € 72 incl. = € 178,51 excl. per jaar. Op 19/06 is eerst CFVK/2026/00353 gemaakt voor 1 kavel (€ 59,50, betaald). Dezelfde dag volgde CFVK/2026/00356 voor 3 kavels (€ 178,51), die meteen gecrediteerd werd (CFVK/2026/00354). Netto is 1 kavel gefactureerd. De volgende factuurdatum staat op 19/07/2027 in plaats van 19/06/2027. Er staat ook nog een conceptofferte S01120 (Smart, 1 kavel) open. Volgens Odoo heeft het gebouw 6 kavels; het aantal appartementen is niet ingevuld.', 'Nagaan wat er afgesproken is: 1 of 3 kavels. Is het 3, dan de 2 kavels bijfactureren. Is het 1, dan het contract op 1 zetten. Volgende factuurdatum op 19/06/2027 zetten, S01120 annuleren.', '[{"id":923135,"label":"Vossenhof","model":"res.partner"},{"id":1114,"label":"S01119","model":"sale.order"},{"id":1115,"label":"S01120","model":"sale.order"},{"id":41547,"label":"CFVK/2026/00353","model":"account.move"},{"id":41562,"label":"CFVK/2026/00354","model":"account.move"},{"id":41606,"label":"CFVK/2026/00356","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c063', 63, 'vme Residentie Herckenrode', 'VME in advies', 'Eén Ponto-koppeling gecrediteerd, het contract rekent er nog twee', '€ 49,59 per jaar', 'Add-on gecrediteerd, staat nog op contract', 'abonnement', 'gemiddeld', 3, 'zeker', 'creditnota', NULL, '2026-10-21', 'De upsell S01352 voegde 2 Ponto-koppelingen toe (€ 98,91, betaald via CFVK/2026/00538). Op 24/09 werd 1 koppeling gecrediteerd (CFVK/2026/00543, € 49,45, nog niet verrekend of terugbetaald). Het contract S01349 telt nog altijd 2 koppelingen, dus bij de verlenging op 21/09/2027 worden er 2 aangerekend. Smart staat hier aan € 84 per kavel in plaats van € 108 (zie de case over afwijkende prijzen). De jaarfactuur CFVK/2026/00535 (€ 924) vervalt op 21/10.', 'Op S01349 het aantal Ponto op 1 zetten, of de creditnota terugdraaien als er toch 2 rekeningen gekoppeld zijn. De creditnota verrekenen met de openstaande factuur.', '[{"id":905243,"label":"vme Residentie Herckenrode","model":"res.partner"},{"id":1343,"label":"S01349","model":"sale.order"},{"id":1346,"label":"S01352","model":"sale.order"},{"id":45016,"label":"CFVK/2026/00538","model":"account.move"},{"id":45145,"label":"CFVK/2026/00543","model":"account.move"},{"id":44966,"label":"CFVK/2026/00535","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c064', 64, 'VME DORPSTRAAT 25 Onr. BE0782.930.550', 'VME in advies', 'Vier facturen en drie creditnota''s voor één jaar; volgende factuur twee maanden te laat', '€ 115,70 (2 maanden)', 'Volgende factuurdatum te ver', 'abonnement', 'gemiddeld', 3, 'zeker', 'dubbel', '2027-02-04', NULL, 'S00748 (start 04/02/2026, € 694,21 per jaar). Bij de start zijn twee facturen gemaakt (CFVK/2026/00077 en 00078), daarna is drie keer gecrediteerd en opnieuw gefactureerd (00083; 00152 + 00153; 00161 + 00162). Netto klopt het: één jaar, betaald via CFVK/2026/00162. Maar de volgende factuurdatum staat op 04/04/2027 in plaats van 04/02/2027: februari en maart 2027 worden niet gefactureerd.', 'Volgende factuurdatum op 04/02/2027 zetten. Navragen waarom er drie correcties nodig waren.', '[{"id":906893,"label":"VME DORPSTRAAT 25 Onr. BE0782.930.550","model":"res.partner"},{"id":748,"label":"S00748","model":"sale.order"},{"id":21033,"label":"CFVK/2026/00077","model":"account.move"},{"id":21076,"label":"CFVK/2026/00078","model":"account.move"},{"id":21280,"label":"CFVK/2026/00083","model":"account.move"},{"id":36844,"label":"CFVK/2026/00152","model":"account.move"},{"id":36887,"label":"CFVK/2026/00153","model":"account.move"},{"id":37037,"label":"CFVK/2026/00161","model":"account.move"},{"id":37081,"label":"CFVK/2026/00162","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c065', 65, 'VME 0840.037.420', 'VME in advies', 'Start 30/03/2026, volgende factuur pas op 25/06/2027', '€ 106,61 (3 maanden)', 'Datums kloppen niet', 'abonnement', 'laag', 5, 'na te kijken', 'ingave', NULL, NULL, 'S00894 (€ 426,44 per jaar) heeft startdatum 30/03/2026, maar het betaalde jaar is CFVK/2026/00373 van 25/06/2026, en de volgende factuurdatum staat op 25/06/2027: 15 maanden na de start. Daarvoor zijn twee facturen gemaakt en weer gecrediteerd (00178 en 00181, met creditnota''s 00180 en 00371). Ofwel startte de klant eigenlijk op 25/06 en klopt de startdatum niet, ofwel worden er 3 maanden niet gefactureerd.', 'Nagaan wanneer de klant echt startte en de startdatum of de volgende factuurdatum rechtzetten.', '[{"id":913033,"label":"VME 0840.037.420","model":"res.partner"},{"id":894,"label":"S00894","model":"sale.order"},{"id":37422,"label":"CFVK/2026/00178","model":"account.move"},{"id":37463,"label":"CFVK/2026/00180","model":"account.move"},{"id":37503,"label":"CFVK/2026/00181","model":"account.move"},{"id":41857,"label":"CFVK/2026/00371","model":"account.move"},{"id":41914,"label":"CFVK/2026/00373","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c066', 66, 'VME Lieven Bauwens I Building te Gent', 'VME in advies', 'Jaar 1 na een jaar gecrediteerd en opnieuw gefactureerd met een ander plan; startdatum klopt niet', 'netto in orde, als het bovenstaande klopt', 'Datums kloppen niet', 'abonnement', 'laag', 5, 'na te kijken', 'ingave', NULL, NULL, 'S00284 (All in, € 892,56, start 04/06/2025) werd pas op 28/05/2026 gecrediteerd (CFVK/2026/00304). Dezelfde dag werd S00286 gefactureerd (Boekhouding Team met korting, € 626,78). Dat order bestond al sinds 30/05/2025, maar heeft startdatum 28/05/2026. Op 16/06 kwam S01112 (Boekhouding Team zonder korting, € 783,47, ook met start 28/05/2026), gefactureerd op 23/06. Als S00286 het eerste jaar is (2025-2026) en S01112 het tweede, klopt het geld. Maar dan staat de startdatum van S00286 een jaar te laat, en lijkt het in Odoo alsof het tweede jaar twee keer betaald is. De dubbele verkoopkans #5022 staat terecht op verloren, maar zonder reden.', 'Bevestigen dat S00286 het eerste jaar is, en de start- en einddatum rechtzetten.', '[{"id":171911,"label":"VME Lieven Bauwens I Building te Gent","model":"res.partner"},{"id":284,"label":"S00284","model":"sale.order"},{"id":286,"label":"S00286","model":"sale.order"},{"id":1107,"label":"S01112","model":"sale.order"},{"id":13984,"label":"CFVK/2025/00088","model":"account.move"},{"id":40172,"label":"CFVK/2026/00304","model":"account.move"},{"id":40187,"label":"CFVK/2026/00305","model":"account.move"},{"id":41681,"label":"CFVK/2026/00361","model":"account.move"},{"id":5022,"label":"#5022 Dubbele verkoopkans - Zie Noan","model":"crm.lead"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c067', 67, '2 klanten', 'Professionele syndicus', 'Maandfactuur twee keer op dezelfde dag; netto in orde', 'geen', 'Dubbel gefactureerd', 'facturatie', 'laag', 5, 'zeker', 'dubbel', NULL, NULL, 'Immo Pauly: CFVK/2026/00124 en 00125 (01/03, elk € 7, S00808). Tax Management Today: CFVK/2026/00258 en 00259 (01/05, elk € 19, S00966). Beide keren schoof de volgende factuurdatum daardoor twee maanden op, zodat de maand erna niet gefactureerd werd. Netto klopt het dus. Het is wel hetzelfde mechanisme als bij de dubbele startfacturen van de jaarabonnementen: wie een tweede factuur maakt, verschuift de volgende factuurdatum.', 'Geen actie nodig in Odoo. Wel meenemen in de regel over dubbele facturen.', '[{"id":906236,"label":"Immo Pauly","model":"res.partner"},{"id":58949,"label":"Tax Management Today","model":"res.partner"},{"id":808,"label":"S00808","model":"sale.order"},{"id":966,"label":"S00966","model":"sale.order"},{"id":22127,"label":"CFVK/2026/00124","model":"account.move"},{"id":22128,"label":"CFVK/2026/00125","model":"account.move"},{"id":39186,"label":"CFVK/2026/00258","model":"account.move"},{"id":39187,"label":"CFVK/2026/00259","model":"account.move"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c068', 68, '8 klanten', 'VME in advies', 'Smart aan € 84 en Basic aan € 48 in plaats van € 108 en € 72', '± € 930 per jaar, als € 108 en € 72 de bedoeling waren', 'Prijs wijkt af', 'facturatie', 'beslissen', 4, 'na te kijken', 'ingave', NULL, NULL, 'Sinds 17/09 hebben 7 nieuwe contracten Smart aan € 84 incl. per kavel (€ 69,42 excl.): S01331, S01343, S01349, S01350, S01315, S01356, S01394. In dezelfde periode kregen andere nieuwe klanten nog € 108 (S01360, S01362, S01316). S01395 (07/10) heeft Basic aan € 48 in plaats van € 72. Er is geen korting ingevuld: de eenheidsprijs zelf is aangepast. Alle orders komen van dezelfde verkoper.', 'Nagaan of er een nieuwe prijs of een actie geldt. Zo ja: als prijslijst in Odoo zetten, zodat elke order dezelfde prijs krijgt. Zo nee: rechtzetten vóór de volgende factuur.', '[{"id":1325,"label":"S01331","model":"sale.order"},{"id":1337,"label":"S01343","model":"sale.order"},{"id":1343,"label":"S01349","model":"sale.order"},{"id":1344,"label":"S01350","model":"sale.order"},{"id":1310,"label":"S01315","model":"sale.order"},{"id":1350,"label":"S01356","model":"sale.order"},{"id":1388,"label":"S01394","model":"sale.order"},{"id":1389,"label":"S01395","model":"sale.order"},{"id":1354,"label":"S01360","model":"sale.order"},{"id":1356,"label":"S01362","model":"sale.order"},{"id":1311,"label":"S01316","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c069', 69, '13 klanten', 'VME in advies', 'Opstarthulp gratis, met korting of achteraf gecrediteerd, zonder vastgelegde reden', 'tot € 206,61 per klant', 'Opstarthulp', 'facturatie', 'beslissen', 4, 'na te kijken', 'afspraak', NULL, NULL, 'Opstarthulp kost € 250 incl. (€ 206,61 excl.). Aan € 0: S00500 (Joost Van Den Vondel), S00510 (Dascottelei 146), S00772 (Sint-Bavo). 100% korting: S00612 (Commerçants). 50% korting: S00563 (Ursmarus), S00574 (Kunstlaan 18 Hasselt), S00631 (Welvaartstraat 27a), S00676 (ACP 118 Roosevelt). € 89,88: S00448 (Het Lo Blok 1). Achteraf gecrediteerd: Letterkunde (CFVK/2026/00570 op 01/10; van CFVK/2026/00496 staat nog € 324 open sinds 30/09) en Bleekhofstraat 28 (CFVK/2026/00409 op 09/07). Gefactureerd maar daarna van het contract verwijderd: Kalendijk (S00602, CFVK/2026/00002). Perwijsveld: apart gefactureerd via S00687, maar de lijn op S00619 staat er nog.', 'Beslissen wanneer opstarthulp gratis of met korting mag, en de reden telkens in de chatter laten noteren. Nooit achteraf crediteren zonder reden, en nooit een lijn verwijderen die al gefactureerd is.', '[{"id":500,"label":"S00500","model":"sale.order"},{"id":510,"label":"S00510","model":"sale.order"},{"id":772,"label":"S00772","model":"sale.order"},{"id":612,"label":"S00612","model":"sale.order"},{"id":563,"label":"S00563","model":"sale.order"},{"id":574,"label":"S00574","model":"sale.order"},{"id":631,"label":"S00631","model":"sale.order"},{"id":676,"label":"S00676","model":"sale.order"},{"id":448,"label":"S00448","model":"sale.order"},{"id":1286,"label":"S01291","model":"sale.order"},{"id":45416,"label":"CFVK/2026/00570","model":"account.move"},{"id":44171,"label":"CFVK/2026/00496","model":"account.move"},{"id":913,"label":"S00913","model":"sale.order"},{"id":42487,"label":"CFVK/2026/00409","model":"account.move"},{"id":602,"label":"S00602","model":"sale.order"},{"id":18690,"label":"CFVK/2026/00002","model":"account.move"},{"id":619,"label":"S00619","model":"sale.order"},{"id":687,"label":"S00687","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c070', 70, '7 klanten', 'VME in advies', 'Abonnement een tweede keer aangemaakt en weer gecrediteerd; netto in orde', 'netto in orde', 'Abonnement dubbel aangemaakt', 'abonnement', 'laag', 5, 'zeker', 'dubbel', NULL, NULL, 'Commerçants 41-43: naast het lopende S00612 nog S00777 en S00791 ("Duplicate Subscription Created"), met twee facturen en twee creditnota''s op 25/02. Welvaartstraat 27a: S00773 naast S00631, plus een extra factuur en creditnota op S00631 zelf. Alfons Schneiderlaan 167-169: S00562 op een dubbel bedrijf (gefactureerd 24/11/2025, gecrediteerd 02/04/2026), S00776 op het andere (start 17/02/2026); tussen november en februari is niets gefactureerd. AGERIS: S00976 is een nieuw abonnement in plaats van de verlenging van S00904. GEOVDP: S00485 en S00513 voor Ponto, een week na elkaar. VME Albertlei: S00921 ("foutief abonnement") op een dubbel bedrijf naast Residentie VME Albertlei 32-34 (S00922). Wenigerstraat 73: S00909 gecrediteerd bij de overstap naar beheer (S01003), wat klopt. Netto is bij al deze klanten correct gefactureerd, behalve mogelijk de periode van Alfons Schneiderlaan. Maar de klant telt telkens als gestopt én nieuw, en er staan creditnota''s die niemand later nog begrijpt.', 'Alfons Schneiderlaan: nagaan of de klant tussen 24/11/2025 en 17/02/2026 al gebruikte. De dubbele bedrijven samenvoegen (zie de case over dubbele bedrijven).', '[{"id":906320,"label":"Résidence Commerçants 41-43","model":"res.partner"},{"id":612,"label":"S00612","model":"sale.order"},{"id":777,"label":"S00777","model":"sale.order"},{"id":791,"label":"S00791","model":"sale.order"},{"id":906343,"label":"VME Welvaartstraat 27a","model":"res.partner"},{"id":631,"label":"S00631","model":"sale.order"},{"id":773,"label":"S00773","model":"sale.order"},{"id":905274,"label":"Alfons Schneiderlaan 167-169, Deurne","model":"res.partner"},{"id":562,"label":"S00562","model":"sale.order"},{"id":905724,"label":"vme Alfons Schneiderlaan 167-169","model":"res.partner"},{"id":776,"label":"S00776","model":"sale.order"},{"id":910106,"label":"AGERIS BY SYNDIA","model":"res.partner"},{"id":904,"label":"S00904","model":"sale.order"},{"id":976,"label":"S00976","model":"sale.order"},{"id":485,"label":"S00485","model":"sale.order"},{"id":513,"label":"S00513","model":"sale.order"},{"id":914137,"label":"VME Albertlei","model":"res.partner"},{"id":921,"label":"S00921","model":"sale.order"},{"id":913831,"label":"Residentie VME Albertlei 32-34","model":"res.partner"},{"id":922,"label":"S00922","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c071', 71, '10 klanten', 'VME in advies', 'Tien abonnementen met 5 tot 17 geannuleerde orders', 'geen, zolang ze geannuleerd blijven', 'Veel geannuleerde orders', 'abonnement', 'laag', 5, 'na te kijken', 'systeem', NULL, NULL, 'Kaasstraat 1 "Gouden Reaal" (S00250, 17 geannuleerd, mei 2025 tot mei 2026), Ringlaan 67 (S00081, 15, binnen een week, Ponto), Res. Vremde 7 (S00334, 12, binnen een dag, Ponto), Res. Beaulieu (S00146, 10), 314 (S00275, 6), Handelslei 85, Haantjeslei 46, Den Herberg, VME Sariera en Beerse Kerkplein 8 (elk 5; Beerse binnen één minuut). Twee soorten: upsells voor Ponto of Peppol die bij het activeren meermaals aangemaakt worden, en orders die elke dag om 05:00 aangemaakt en geannuleerd worden (Den Herberg, 314, Sariera), wat op een automatische taak wijst. Zolang ze geannuleerd zijn kost het niets, maar één vergeten exemplaar wordt gefactureerd (zie de cases van de Serre en Brutopia).', 'Nagaan welke automatische taak om 05:00 orders aanmaakt, en waarom het platform bij het activeren van een add-on meer dan één upsell maakt.', '[{"id":250,"label":"S00250","model":"sale.order"},{"id":81,"label":"S00081","model":"sale.order"},{"id":334,"label":"S00334","model":"sale.order"},{"id":146,"label":"S00146","model":"sale.order"},{"id":275,"label":"S00275","model":"sale.order"},{"id":28,"label":"S00028","model":"sale.order"},{"id":93,"label":"S00093","model":"sale.order"},{"id":240,"label":"S00240","model":"sale.order"},{"id":297,"label":"S00297","model":"sale.order"},{"id":1223,"label":"S01228","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c072', 72, '14 klanten', 'VME in advies', '15 upsells staan als offerte open, de oudste sinds december 2025', '€ 397,70 per jaar', 'Offerte open', 'abonnement', 'gemiddeld', 3, 'na te kijken', 'opvolging', NULL, NULL, 'Elk is een add-on (Ponto of Peppol) die de klant aanvroeg, verzonden maar niet bevestigd: S00627 (Vme jens), S00699 (Res. Beaulieu), S00717 (VME Ringlaan 67), S00833 (VME Haspengouwstraat 21), S00844 (VME Handelslei 85), S00862 (ACP Lambermont 362), S00863 (ACP Lambermont 362), S01083 (ACP Emile Bockstael 268), S01089 (VME Haantjeslei 211), S01109 (VME ERANTHIS), S01180 (VME Wenigerstraat 73 Borsbee), S01183 (de Serre), S01194 (VME Brutopia), S01215 (VME Fruithoflaan 39), S01235 (Prins Albertlei 25). Samen € 397,70 excl. per jaar. Lambermont 362 heeft er twee identieke. S01180 (Wenigerstraat 73) en S01183 (de Serre) zijn dubbels van een upsell die wel bevestigd is; S01194 (Brutopia) is een vierde exemplaar naast twee bevestigde en een geannuleerde. Gebruikt de klant de koppeling al, dan betaalt hij er niet voor; zo niet, dan hoort de offerte geannuleerd te worden.', 'Per offerte nagaan of de koppeling actief is: bevestigen en factureren, of annuleren.', '[{"id":627,"label":"S00627","model":"sale.order"},{"id":699,"label":"S00699","model":"sale.order"},{"id":717,"label":"S00717","model":"sale.order"},{"id":833,"label":"S00833","model":"sale.order"},{"id":844,"label":"S00844","model":"sale.order"},{"id":862,"label":"S00862","model":"sale.order"},{"id":863,"label":"S00863","model":"sale.order"},{"id":1078,"label":"S01083","model":"sale.order"},{"id":1084,"label":"S01089","model":"sale.order"},{"id":1104,"label":"S01109","model":"sale.order"},{"id":1175,"label":"S01180","model":"sale.order"},{"id":1178,"label":"S01183","model":"sale.order"},{"id":1189,"label":"S01194","model":"sale.order"},{"id":1210,"label":"S01215","model":"sale.order"},{"id":1230,"label":"S01235","model":"sale.order"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c073', 73, '± 25 klanten', 'VME in advies', '32 offertes staan maanden open, waarvan 6 voor testbedrijven', 'administratief', 'Offerte open', 'abonnement', 'laag', 5, 'zeker', 'opvolging', NULL, NULL, 'De oudste: S00357 Facade Vastgoed (13/08/2025), S00402 Pelgrimsplein 20, S00470 GEOVDP (17 × Ponto, € 843,03), S00481 Ruth Adam. VME Gilmar heeft er drie (S00702, S00953, S01002), naast een openstaande verlenging. Beerse Kerkplein 8 heeft er twee (S01229, S01258) naast een lopend contract. Res. Alphée twee identieke (S00875, S00881). Voor testbedrijven: TEST VME THOMAS (S01219 tot S01222), Test 2 (S01223) en VME Demo Residentie Waterloo (S00724). S00499 (Joost Van Den Vondel) staat als verzonden concept naast het lopende S00500. Een open offerte kan nog bevestigd worden, ook als ze niet meer klopt.', 'Annuleren wat niet meer geldt; bevestigen wat de klant nog wil.', '[{"id":357,"label":"S00357","model":"sale.order"},{"id":402,"label":"S00402","model":"sale.order"},{"id":470,"label":"S00470","model":"sale.order"},{"id":481,"label":"S00481","model":"sale.order"},{"id":499,"label":"S00499","model":"sale.order"},{"id":645,"label":"S00645","model":"sale.order"},{"id":702,"label":"S00702","model":"sale.order"},{"id":712,"label":"S00712","model":"sale.order"},{"id":813,"label":"S00813","model":"sale.order"},{"id":875,"label":"S00875","model":"sale.order"},{"id":881,"label":"S00881","model":"sale.order"},{"id":940,"label":"S00940","model":"sale.order"},{"id":953,"label":"S00953","model":"sale.order"},{"id":995,"label":"S00995","model":"sale.order"},{"id":1002,"label":"S01002","model":"sale.order"},{"id":1099,"label":"S01104","model":"sale.order"},{"id":1115,"label":"S01120","model":"sale.order"},{"id":1196,"label":"S01201","model":"sale.order"},{"id":1224,"label":"S01229","model":"sale.order"},{"id":1253,"label":"S01258","model":"sale.order"},{"id":1214,"label":"S01219","model":"sale.order"},{"id":1218,"label":"S01223","model":"sale.order"},{"id":724,"label":"S00724","mod