ie Borsbeeksebrug (482)","model":"res.partner"},{"id":501,"label":"hansbaumanns77@gmail.com (501)","model":"res.partner"},{"id":503,"label":"Hans Baumanns (503)","model":"res.partner"},{"id":506,"label":"Ter Heydelaan 440 (506)","model":"res.partner"},{"id":510,"label":"ANSELMO (510)","model":"res.partner"},{"id":527,"label":"VME Residentie Berkenhof (527)","model":"res.partner"},{"id":561,"label":"F100 (561)","model":"res.partner"},{"id":584,"label":"VME Jozef Verbovenlei 130 (584)","model":"res.partner"},{"id":710,"label":"Jeruzalemstraat 12 (710)","model":"res.partner"},{"id":726,"label":"HEVACO BEHEER (726)","model":"res.partner"},{"id":730,"label":"03beheer (730)","model":"res.partner"},{"id":2614,"label":"Athena (2614)","model":"res.partner"},{"id":6328,"label":"TST (6328)","model":"res.partner"},{"id":59014,"label":"VME gebouw Residentie Gezelle Guido Gezellestraat 22-26 (59014)","model":"res.partner"},{"id":59178,"label":"kmo-parken.be (59178)","model":"res.partner"},{"id":59183,"label":"VME Italiëlei 85 (59183)","model":"res.partner"},{"id":59257,"label":"VME Weeldestraat 149 (59257)","model":"res.partner"},{"id":59258,"label":"Agence Verburgh (59258)","model":"res.partner"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c082', 82, '4 gebouwen', 'VME in advies', 'Expert die geen professionele syndicus is', 'administratief', 'Gegevens', 'partners', 'laag', 5, 'waarschijnlijk', 'ingave', NULL, NULL, 'Mille BV (316) staat als "VME in advies" maar is expert van Bogiegebouw, Residentie Embrechts en Developer VME. Rob de Verzekeraar (487), ook "VME in advies", is expert van Boho. Ofwel klopt het klanttype van de expert niet, ofwel de koppeling (de namen doen aan testgegevens denken).', 'Klanttype of expert rechtzetten, of als test markeren.', '[{"id":316,"label":"Mille BV","model":"res.partner"},{"id":907041,"label":"Bogiegebouw","model":"res.partner"},{"id":907042,"label":"Residentie Embrechts","model":"res.partner"},{"id":907043,"label":"Developer VME","model":"res.partner"},{"id":487,"label":"Rob de Verzekeraar","model":"res.partner"},{"id":907678,"label":"Boho","model":"res.partner"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c083', 83, '6 VME''s', 'VME in advies', '6 betalende VME''s zonder postcode', 'administratief', 'Gegevens', 'partners', 'laag', 5, 'zeker', 'gegevens', NULL, NULL, 'Residentie De Sportwereld, K. Deswertlaan 1A 8370 Blankenberge, VME Couteau''s, JVR282, Hendrik Meyslaan 34, De Wand. De postcode bepaalt de regio in de rapporten en de plaats op de kaart.', 'Postcode invullen.', '[{"id":913172,"label":"Residentie De Sportwereld","model":"res.partner"},{"id":917972,"label":"K. Deswertlaan 1A 8370 Blankenberge","model":"res.partner"},{"id":918443,"label":"VME Couteau''s","model":"res.partner"},{"id":921713,"label":"JVR282","model":"res.partner"},{"id":930936,"label":"Hendrik Meyslaan 34","model":"res.partner"},{"id":938490,"label":"De Wand","model":"res.partner"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c084', 84, '8 klanten', 'VME in advies', '10 verkoopkansen op verloren, terwijl de klant wel tekende; bij 5 hangt de gewonnen kans aan een dubbel bedrijf', 'conversiecijfers', 'Verkoopkans niet afgesloten', 'crm', 'gemiddeld', 3, 'waarschijnlijk', 'gegevens', NULL, NULL, 'Deze kansen staan op verloren, terwijl de klant daarna (of dezelfde dag) een abonnement startte, en voor die klant bestaat geen gewonnen kans. 8 van de 10 hebben geen verliesreden. Bij 5 staat de gewonnen kans op een dubbel van de klant: Tannhauser (#5852 en #5859; gewonnen #6794 op het bedrijf "Ivo Van Assche"), Bogaerts (#6515 en #7238; gewonnen #6311 op "Wouters gebouw"), Alphonse Balat (#7298; gewonnen #5994 op een tweede "Residentie Alphonse Balat"), Hollezijp (#7369; gewonnen #6748 op "Vereniging van Mede-eigenaars … Hollezijp") en KMO De 7 Nete (#7399; gewonnen #5943 op "Neteweg 7, 2850 Boom"). Zonder gewonnen kans: Gennaker (#7376), Boomgaardstraat 180-182 (#6224 "VME Sariera") en Vastgoed Janssens (#5237, reden Timing; klant sinds 01/02/2026).', 'De dubbele bedrijven samenvoegen, zodat de gewonnen kans bij de betalende klant staat. Een verloren kans van een klant die tekende op gewonnen zetten. Zolang dat niet gebeurt, telt de omzet niet mee in de conversie per kanaal en per verkoper.', '[{"id":5852,"label":"#5852 Ivo Van Assche''s verkoopkans","model":"crm.lead"},{"id":5859,"label":"#5859 Demo Contactaanvraag - Ivo Van Assche","model":"crm.lead"},{"id":6515,"label":"#6515 Demo Contactaanvraag - Wouter Pauwels","model":"crm.lead"},{"id":7238,"label":"#7238 Wouter Pauwels''s verkoopkans","model":"crm.lead"},{"id":7298,"label":"#7298 Ann Gillesjans''s verkoopkans","model":"crm.lead"},{"id":7369,"label":"#7369 Jan Naegels''s verkoopkans","model":"crm.lead"},{"id":7399,"label":"#7399 Lieve Van Stichel''s verkoopkans","model":"crm.lead"},{"id":7376,"label":"#7376 Lieven Nys''s verkoopkans","model":"crm.lead"},{"id":6224,"label":"#6224 VME Sariera''s verkoopkans","model":"crm.lead"},{"id":5237,"label":"#5237 Marleen Janssens''s verkoopkans","model":"crm.lead"},{"id":6794,"label":"#6794 Ivo Van Assche''s verkoopkans","model":"crm.lead"},{"id":6311,"label":"#6311 Meta Lead via IG:  Wouter Pauwels","model":"crm.lead"},{"id":5994,"label":"#5994 Ann Gillesjans''s verkoopkans","model":"crm.lead"},{"id":6748,"label":"#6748 Jan Naegels''s verkoopkans","model":"crm.lead"},{"id":5943,"label":"#5943 Lieve Van Stichel''s verkoopkans","model":"crm.lead"},{"id":905333,"label":"VME Residentie Tannhauser","model":"res.partner"},{"id":906626,"label":"Ivo Van Assche","model":"res.partner"},{"id":910622,"label":"Residentie Bogaerts","model":"res.partner"},{"id":906387,"label":"Wouters gebouw","model":"res.partner"},{"id":911711,"label":"Residentie Alphonse Balat","model":"res.partner"},{"id":905415,"label":"Residentie Alphonse Balat","model":"res.partner"},{"id":912828,"label":"VME Residentie Hollezijp","model":"res.partner"},{"id":906990,"label":"Vereniging van Mede-eigenaars van het gebouw Residentie Hollezijp Hollezijp 1-3 te Boom","model":"res.partner"},{"id":913015,"label":"VME KMO De 7 Nete","model":"res.partner"},{"id":905474,"label":"Neteweg 7, 2850 Boom","model":"res.partner"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c085', 85, '42 verkoopkansen', 'VME in advies', '42 gewonnen verkoopkansen zonder order bij dat bedrijf', 'conversiecijfers', 'Verkoopkans niet afgesloten', 'crm', 'laag', 5, 'na te kijken', 'gegevens', NULL, NULL, 'Een gewonnen kans hoort bij een bevestigde order van hetzelfde bedrijf. Hier niet. De oorzaken: (1) de kans hangt aan een dubbel van de klant (zie #78); (2) de kans hangt aan een "bedrijf" met de naam van een persoon en zonder klanttype, bijvoorbeeld Ivo Van Assche, Lutgart Forceville, Mon Doupagne, Christophe Samsom, Isabelle Linclau, Erik Herregodts, Christophe Thilmany, Willem Demonie en Philip Van Edom; (3) de kans hangt aan een professionele syndicus waarvan de gebouwen betalen (D & G Beheer, Tom De Ruyck, Syndexia); (4) Syndicoach-aanvragen (Koen Claeys, Stephanie Debaste, Aisha De Borger): Syndicoach factureert nog niet in Odoo, dus dat is verwacht; (5) testbedrijven (test, VME Butterfly Solutions, Eigen_Syndic, Vasthoet-beheer); (6) Free Trial-VME''s die nooit betaalden: De Post, The Waves Sand, Egelsvennen, Residentie Nivelles 1, PHOENIX ACP en Sint-Joris Brugge.', 'Regel afspreken: gewonnen = bevestigde order, op het bedrijf van die order. Bij (2) het bedrijf met de persoonsnaam omzetten naar een contactpersoon onder de VME. Bij (6) de kans terug op open of op verloren zetten.', '[{"id":3861,"label":"#3861 Lutgart Forceville''s verkoopkans","model":"crm.lead"},{"id":4152,"label":"#4152 Mon Doupagne''s verkoopkans","model":"crm.lead"},{"id":4243,"label":"#4243 Marc Vandenbogarde''s verkoopkans","model":"crm.lead"},{"id":5205,"label":"#5205 Gustaaf Verbeke''s verkoopkans","model":"crm.lead"},{"id":5922,"label":"#5922 Meta Lead via IG:  christophesamsom","model":"crm.lead"},{"id":6238,"label":"#6238 Tinne Lenaerts''s verkoopkans","model":"crm.lead"},{"id":6262,"label":"#6262 Demo Contactaanvraag - Isabelle Linclau","model":"crm.lead"},{"id":6642,"label":"#6642 Demo Contactaanvraag - Erik Herregodts","model":"crm.lead"},{"id":6718,"label":"#6718 Christophe Thilmany''s verkoopkans","model":"crm.lead"},{"id":6761,"label":"#6761 BALCAEN Renaat''s verkoopkans","model":"crm.lead"},{"id":6794,"label":"#6794 Ivo Van Assche''s verkoopkans","model":"crm.lead"},{"id":6960,"label":"#6960 Retail Syndic''s verkoopkans","model":"crm.lead"},{"id":7167,"label":"#7167 Christophe THILMANY''s verkoopkans","model":"crm.lead"},{"id":7674,"label":"#7674 Jérôme Santy''s verkoopkans","model":"crm.lead"},{"id":10824,"label":"#10824 biv.be PS Verkoopkans Philip Van Edom","model":"crm.lead"}]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z'),
  ('c086', 86, '199 leads', NULL, '199 leads en verkoopkansen in 2026 gesloten zonder verliesreden', 'rapportering', 'Verkoopkans niet afgesloten', 'crm', 'laag', 5, 'zeker', 'opvolging', NULL, NULL, '174 verkoopkansen en 25 leads zijn in 2026 gearchiveerd of verloren gezet zonder verliesreden. Zonder reden is niet te zien of een klant afhaakte op prijs, timing of omdat hij bij een concurrent tekende, en staan dubbels (zoals #5022) tussen de echte verliezen.', 'De verliesreden verplicht maken, of wekelijks de kansen zonder reden nalopen. Een dubbel krijgt een eigen reden ("Dubbel").', '[]'::jsonb, false, false, false, false, false, '', '', '', '', NULL, NULL, NULL, NULL, NULL, '2026-10-16T07:28:44.783Z', 0, '2026-10-16T07:28:44.783Z')
